// Types and helpers for the photo albums. The data is generated by scripts/build_gallery.py from
// the folders in gallery/ (see gallery/README.md): gallery.json has every album (see galleryAlbums.ts,
// which only the gallery pages load) and gallery-home.json has the few photos on the home page.
// Edit gallery/<album>/album.json, not the generated files.

export interface GalleryPhoto {
  id: string
  width: number
  height: number
  widths: number[]                  // the published sizes, smallest first
  color: string                     // the photo's average colour, shown until it loads
  alt: string
  caption?: string
  position?: string                 // which part to keep when a tile crops it (CSS object-position)
  date?: string                     // the day it was taken, e.g. "Oct 25, 2026 (AoE)"
}

export interface GalleryAlbumInfo {
  slug: string
  title: string
  tone: string                      // its colours: coral, periwinkle, sage or butter
  context?: string                  // what the trip was for, e.g. "EMNLP 2026"
  date?: string                     // the days its photos were taken, e.g. "Oct 24–25, 2026 (AoE)"
}

export interface GalleryAlbum extends GalleryAlbumInfo {
  link?: { label: string; href: string }
  cover: string                     // id of the photo on the folder
  photos: GalleryPhoto[]
}

export const albumTone = (a: Pick<GalleryAlbumInfo, 'tone'>) => `gal-tone-${a.tone}`

/** A tooltip for dates given in AoE. */
export const dateTitle = (date: string) => (date.includes('AoE') ? 'Anywhere on Earth (UTC−12)' : undefined)

type Slugged = Pick<GalleryAlbumInfo, 'slug'>

export const albumPath = (a: Slugged) => `/gallery/${a.slug}/`
export const coverOf = (a: GalleryAlbum) => a.photos.find(p => p.id === a.cover) ?? a.photos[0]
export const countPhotos = (n: number) => `${n} photo${n === 1 ? '' : 's'}`

export const photoUrl = (a: Slugged, p: GalleryPhoto, width = p.widths[0]) =>
  `/gallery/${a.slug}/${p.id}-${width}.webp`
export const photoSrcSet = (a: Slugged, p: GalleryPhoto) =>
  p.widths.map(w => `${photoUrl(a, p, w)} ${w}w`).join(', ')
